const DICTS = {en, he};
const LKEY = 'workbench.lang';
let lang = (()=>{ try { return localStorage.getItem(LKEY) || 'he'; } catch(e){ return 'he'; } })();
if (!DICTS[lang]) lang = 'he';

export const getLang = ()=>lang;
export const locale = ()=>lang === 'he' ? 'he-IL' : 'en-GB';
export function setLang(l){
  lang = DICTS[l] ? l : 'he';
  try { localStorage.setItem(LKEY, lang); } catch(e){}
  document.documentElement.lang = lang;
  document.documentElement.dir = lang === 'he' ? 'rtl' : 'ltr';
}
function lookup(k){
  const v = DICTS[lang][k] ?? en[k];
  if (v === undefined) console.warn('[i18n] missing key', k);
  return v ?? k;
}
export function t(k, vars){
  let v = lookup(k);
  if (typeof v === 'function') v = v(vars?.n ?? 0);
  if (vars) v = String(v).replace(/\{(\w+)\}/g, (m, name)=>name in vars ? vars[name] : m);
  return v;
}
export function tn(k, n, vars){
  const v = lookup(k);
  const s = typeof v === 'function' ? v(n) : String(v);
  return s.replace(/\{(\w+)\}/g, (m, name)=>name === 'n' ? n : vars && name in vars ? vars[name] : m);
}
export const _dicts = DICTS;
